export function resolveLinkPath(
  link: string | undefined,
  loopItem: Record<string, unknown> | null,
  routeParams: Record<string, string>
): string | undefined {
  if (!link || !link.trim()) return undefined;
  let resolved = link.trim();

  // If it's a JS statement or function call (e.g. setState, set, etc.), it is NEVER a navigation link
  if (resolved.startsWith('setState(') || resolved.includes('setState(') || resolved.startsWith('set(') || resolved.startsWith('execFunc(') || resolved.includes('=>')) {
    return undefined;
  }

  const navMatch = resolved.match(/(?:navigate|onNavigate|goto|push)s*(s*['"]([^'"]+)['"]s*)/i);
  if (navMatch) {
    resolved = navMatch[1];
  } else if (!resolved.startsWith('/') && !resolved.startsWith('http://') && !resolved.startsWith('https://') && !resolved.startsWith('#')) {
    return undefined;
  }

  resolved = resolved.replace(/:([a-zA-Z0-9_]+)/g, (match, paramName, offset) => {
    let val: string | undefined;
    if (loopItem && loopItem[paramName] !== undefined && loopItem[paramName] !== null) {
      val = String(loopItem[paramName]);
    } else if (routeParams && routeParams[paramName] !== undefined) {
      val = routeParams[paramName];
    }
    if (val !== undefined) {
      const qIdx = resolved.indexOf('?');
      return (qIdx !== -1 && offset > qIdx) ? encodeURIComponent(val) : val;
    }
    return match;
  });

  resolved = resolved.replace(/{{([^}]+)}}/g, (match, fieldName, offset) => {
    const key = fieldName.trim();
    let val: string | undefined;
    if (loopItem && loopItem[key] !== undefined && loopItem[key] !== null) {
      val = String(loopItem[key]);
    } else if (routeParams && routeParams[key] !== undefined) {
      val = routeParams[key];
    }
    if (val !== undefined) {
      const qIdx = resolved.indexOf('?');
      return (qIdx !== -1 && offset > qIdx) ? encodeURIComponent(val) : val;
    }
    return match;
  });

  return resolved;
}

// Hook to track window innerWidth on resize
export const useWindowWidth = (): number => {
  const [width, setWidth] = useState<number>(() => (typeof window !== 'undefined' ? window.innerWidth : 1200));

  useEffect(() => {
    if (typeof window === 'undefined') return;
    const handleResize = () => setWidth(window.innerWidth);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  return width;
};

// Merges mobile-first responsive overrides into a component node based on viewport width
export function resolveResponsiveNode<T extends ComponentNode>(node: T, viewportWidth: number): T {
  if (!node) return node;

  const responsiveObj = node.responsive || (node.style as any)?.responsive;
  if (!responsiveObj) return node;

  const activeBreakpoints: (keyof ResponsiveBreakpoints)[] = [];
  if (viewportWidth < 768) {
    if (responsiveObj.sm) activeBreakpoints.push('sm');
  } else if (viewportWidth < 1024) {
    if (responsiveObj.md) {
      activeBreakpoints.push('md');
    } else if (responsiveObj.sm) {
      activeBreakpoints.push('sm');
    }
  } else {
    if (responsiveObj.lg) activeBreakpoints.push('lg');
    if (viewportWidth >= 1280 && responsiveObj.xl) activeBreakpoints.push('xl');
  }

  if (activeBreakpoints.length === 0) return node;

  let merged: T = { ...node };

  for (const bp of activeBreakpoints) {
    const override = responsiveObj[bp];
    if (override && typeof override === 'object') {
      const { style: overrideStyle, ...otherOverrides } = override as Record<string, any>;
      
      const mergedStyle = overrideStyle || merged.style
        ? { ...(merged.style || {}), ...(overrideStyle || {}) }
        : undefined;

      merged = {
        ...merged,
        ...otherOverrides,
        ...(mergedStyle ? { style: mergedStyle } : {}),
      };
    }
  }

  return merged;
}

// Generic helper to match items against a selected category filter
export function matchesCategoryFilter(item: Record<string, unknown> | any, categoryFilter: string | undefined): boolean {
  if (!categoryFilter || !categoryFilter.trim() || categoryFilter === 'all' || categoryFilter === 'All') return true;
  if (!item || typeof item !== 'object') return false;

  const target = categoryFilter.trim().toLowerCase();

  const normalize = (val: string) => {
    const s = val.trim().toLowerCase();
    return s.endsWith('s') ? s.slice(0, -1) : s;
  };
  const normTarget = normalize(target);

  const checkMatch = (val: unknown): boolean => {
    if (val === null || val === undefined) return false;
    if (typeof val === 'string') {
      const s = val.trim().toLowerCase();
      if (s === target || normalize(s) === normTarget) return true;
      if (s.includes(target) || target.includes(s)) return true;
      return false;
    }
    if (typeof val === 'number') {
      return String(val) === target;
    }
    if (Array.isArray(val)) {
      return val.some((v) => checkMatch(v));
    }
    if (typeof val === 'object') {
      const obj = val as Record<string, unknown>;
      return (
        checkMatch(obj.id) ||
        checkMatch(obj.name) ||
        checkMatch(obj.title) ||
        checkMatch(obj.slug) ||
        checkMatch(obj.category)
      );
    }
    return false;
  };

  const candidateFields = [
    item.category,
    item.category_id,
    item.categoryId,
    item.category_name,
    item.categoryName,
    item.categories,
    item.tag,
    item.tags,
    item.type,
    item.collection,
    item.name,
    item.id,
  ];

  return candidateFields.some((field) => checkMatch(field));
}

// Generic helper to match items against search keywords
export function matchesSearchFilter(item: Record<string, unknown> | any, searchQuery: string | undefined): boolean {
  if (!searchQuery || !searchQuery.trim()) return true;
  if (!item || typeof item !== 'object') return false;

  const q = searchQuery.trim().toLowerCase();
  const searchFields = [
    item.name,
    item.title,
    item.description,
    item.category,
    item.category_name,
    item.tags,
    item.type,
    item.material,
    item.finish,
  ];

  return searchFields.some((val) => {
    if (!val) return false;
    if (typeof val === 'string') return val.toLowerCase().includes(q);
    if (Array.isArray(val)) return val.some((v) => typeof v === 'string' && v.toLowerCase().includes(q));
    return false;
  });
}

// Evaluates a conditional expression safely against runtime state, loop item and route params
export function evaluateCondition(
  condition: string | undefined,
  ctx: { states: Record<string, any>; item?: any; loopItem?: any; routeParams?: Record<string, string> }
): boolean {
  if (!condition || typeof condition !== 'string' || !condition.trim()) return false;
  try {
    const fn = new Function('states', 'item', 'loopItem', 'routeParams', `return Boolean(${condition.trim()});`);
    return Boolean(fn(ctx.states || {}, ctx.item || ctx.loopItem || {}, ctx.loopItem || ctx.item || {}, ctx.routeParams || {}));
  } catch {
    return false;
  }
}

// Dynamically resolves state styles and property overrides (e.g. normal, selected, unselected, active)
export function resolveNodeWithStates<T extends ComponentNode>(
  node: T,
  states: Record<string, any>,
  loopItem: any,
  routeParams: any
): T {
  if (!node || !node.states || typeof node.states !== 'object') return node;

  let merged: T = { ...node };

  // 1. Base 'normal' or 'default' state
  if (node.states.normal && typeof node.states.normal === 'object') {
    const { style: normalStyle, when: _w, condition: _c, ...normalProps } = node.states.normal as any;
    merged = {
      ...merged,
      ...normalProps,
      style: normalStyle ? { ...(merged.style || {}), ...normalStyle } : merged.style,
    };
  }
  if (node.states.default && typeof node.states.default === 'object') {
    const { style: defaultStyle, when: _w, condition: _c, ...defaultProps } = node.states.default as any;
    merged = {
      ...merged,
      ...defaultProps,
      style: defaultStyle ? { ...(merged.style || {}), ...defaultStyle } : merged.style,
    };
  }

  // 2. Conditional states (e.g. 'selected', 'unselected', 'active', etc.)
  for (const [stateKey, stateDef] of Object.entries(node.states)) {
    if (stateKey === 'normal' || stateKey === 'default' || !stateDef || typeof stateDef !== 'object') continue;

    const condition = (stateDef as any).when || (stateDef as any).condition;
    if (condition && evaluateCondition(condition, { states, item: loopItem, loopItem, routeParams })) {
      const { style: stateStyle, when: _w, condition: _c, ...otherProps } = stateDef as any;
      merged = {
        ...merged,
        ...otherProps,
        style: stateStyle ? { ...(merged.style || {}), ...stateStyle } : merged.style,
      };
    }
  }

  return merged;
}

