// Ensure every node in the tree has a unique ID
export function ensureUniqueIds(node: ComponentNode, prefix: string = 'comp'): ComponentNode {
  if (!node || typeof node !== 'object') return node;
  const typeName = (node.type || 'node').toLowerCase().replace(/_/g, '');
  const uniqueId = node.id || `${prefix}_${typeName}_${Math.random().toString(36).substr(2, 6)}`;
  const updatedNode = { ...node, id: uniqueId } as any;
  if (Array.isArray(updatedNode.children)) {
    updatedNode.children = updatedNode.children.map((child: ComponentNode, idx: number) =>
      ensureUniqueIds(child, `${uniqueId}_${idx}`)
    );
  }
  if (updatedNode.child) {
    updatedNode.child = ensureUniqueIds(updatedNode.child, `${uniqueId}_0`);
  }
  return updatedNode as ComponentNode;
}

// Find a node by its unique ID
export function findNodeById(root: ComponentNode | null, targetId: string | null): ComponentNode | null {
  if (!root || !targetId) return null;
  if (root.id === targetId) return root;
  if ('children' in root && Array.isArray(root.children)) {
    for (const child of root.children) {
      const found = findNodeById(child, targetId);
      if (found) return found;
    }
  }
  if ('child' in root && (root as SizedBoxNode).child) {
    const found = findNodeById((root as SizedBoxNode).child!, targetId);
    if (found) return found;
  }
  return null;
}

// Find the parent node of a target node by ID
export function findParentNode(root: ComponentNode | null, targetId: string | null): ComponentNode | null {
  if (!root || !targetId || root.id === targetId) return null;
  if ('children' in root && Array.isArray((root as ContainerNode).children)) {
    for (const child of ((root as ContainerNode).children || [])) {
      if (child.id === targetId) return root;
      const found = findParentNode(child, targetId);
      if (found) return found;
    }
  }
  if ('child' in root && (root as SizedBoxNode).child) {
    if ((root as SizedBoxNode).child!.id === targetId) return root;
    const found = findParentNode((root as SizedBoxNode).child!, targetId);
    if (found) return found;
  }
  return null;
}

// Get path of ancestor nodes leading to target node (root first, parent last)
export function getNodeAncestors(root: ComponentNode | null, targetId: string | null): ComponentNode[] {
  if (!root || !targetId) return [];
  const ancestors: ComponentNode[] = [];

  function dfs(curr: ComponentNode, path: ComponentNode[]): boolean {
    if (curr.id === targetId) {
      ancestors.push(...path);
      return true;
    }
    if ('children' in curr && Array.isArray((curr as ContainerNode).children)) {
      for (const child of ((curr as ContainerNode).children || [])) {
        if (dfs(child, [...path, curr])) return true;
      }
    }
    if ('child' in curr && (curr as SizedBoxNode).child) {
      if (dfs((curr as SizedBoxNode).child!, [...path, curr])) return true;
    }
    return false;
  }

  dfs(root, []);
  return ancestors;
}

// Update a node by its unique ID (immutable)
export function updateNodeById(
  root: ComponentNode,
  targetId: string,
  updatedFields: Partial<ComponentNode>
): ComponentNode {
  if (!root || !targetId) return root;
  if (root.id === targetId) return { ...root, ...updatedFields } as ComponentNode;
  const clone = { ...root } as any;
  if (Array.isArray(clone.children)) {
    clone.children = clone.children.map((child: ComponentNode) =>
      updateNodeById(child, targetId, updatedFields)
    );
  }
  if (clone.child) {
    clone.child = updateNodeById(clone.child, targetId, updatedFields);
  }
  return clone as ComponentNode;
}

// Delete a node by its unique ID (immutable). Returns null if the root itself is deleted.
export function deleteNodeById(
  root: ComponentNode,
  targetId: string,
): ComponentNode | null {
  if (!root || !targetId) return root;
  if (root.id === targetId) return null;
  const clone = { ...root } as any;
  if (Array.isArray(clone.children)) {
    clone.children = clone.children
      .map((child: ComponentNode) => deleteNodeById(child, targetId))
      .filter(Boolean);
  }
  if (clone.child) {
    const next = deleteNodeById(clone.child, targetId);
    clone.child = next ?? undefined;
  }
  return clone as ComponentNode;
}

